solutionCode:
#include <stdio.h>

/* Ficha do aluno: imprime as tres linhas da ficha.
   Este bloco em cima da funcao e o comentario de cabecalho dela. */
void fichaComentada(void) {
    printf("ficha do aluno\n");  // o titulo da ficha
    printf("nome: Ana\n");       // o nome de quem e a ficha
    printf("turma: C1\n");       // a turma do aluno
}
